                solve();
            } catch (RuntimeException e) {
                if (!"Clean exit".equals(e.getMessage())) {
                    throw e;
                }
            } finally {
                io.close();
            }
        }

        void solve() {
            long n = io.nextLong();
            long m = io.nextLong();
            if (m < n) {
                long temp = m;
                m = n;
                n = temp;
            }

            if (n == 1) {
                io.println(brute1(m));
                return;
            }
            if (n == 2) {
                if (m < 3) io.println(0);
                else if (m == 3) io.println(4);
                else if (m == 7) io.println(12);
                else io.println(2 * m);
                return;
            }

            io.println(2 * (n * m / 2));
        }

        long brute1(long m) {
            long ans = 6 * (m / 6);
            long remainder = m % 6;
            if (remainder == 5) ans += 4;
            else if (remainder == 4) ans += 2;
            return ans;
        }

        class IO extends PrintWriter {
            private InputStreamReader r;
            private static final int BUFSIZE = 1 << 15;
            private char[] buf;
            private int bufc;
            private int bufi;
            private StringBuilder sb;

            public IO() {
                super(new BufferedOutputStream(System.out));
                r = new InputStreamReader(System.in);
                buf = new char[BUFSIZE];
                bufc = 0;
                bufi = 0;
                sb = new StringBuilder();
            }

            private void fillBuf() throws IOException {
                bufi = 0;
                bufc = 0;
